func voice(key: String, vol: float, pan: float, radio: bool) -> float:
	var v = AUD.voice.get(key)
	if v == null:
		return 2.0
	_play(_stream("res://voice/" + v.f), vol / 0.9 * (1.4 if radio else 1.0), pan, radio)
	return v.dur

func _up(id: int) -> void:
	var roam: Dictionary = game.roam
	if roam.get("sprintId") == id:
		roam.sprint = false
		roam.sprintId = null
	if drag and drag.id == id:
		drag = null
	if roam.joy and roam.joy.id == id:
		roam.joy = null
	if roam.look and roam.look.id == id:
		roam.look = null
	if M and M.hold and M.hold.id == id:
		M.hold = null

func _aabb(n: Node) -> AABB:
	var res = AABB()
	var first = true
	for mi in n.find_children("*", "MeshInstance3D", true, false):
		var a: AABB = (mi as MeshInstance3D).global_transform * (mi as MeshInstance3D).get_aabb()
		if first:
			res = a
			first = false
		else:
			res = res.merge(a)
	return res

func draw_collapse(t: float) -> void:
	var st: float = game.scene_t
	rect(0, 0, HW, HH, Color(0.15, 0.25, 0.0, 0.25 + 0.1 * sin(t * 3)))
	vignette(1.0)
	if st > 1.6:
		rect(0, 0, HW, HH, Color(0, 0, 0, clampf((st - 1.6) / 2.2, 0, 1)))
	if st > 4.6:
		game.S = "dead"
		game.scene_t = 0.0

func set_buzz(on: bool, pan := 0.0) -> void:
	buzz.stop()
	if on:
		buzz.bus = _bus_for(pan, false)
		buzz.play()

func dev_act(f: Callable, msg: String) -> Callable:
	return func():
		f.call()
		game.audio.sfx("click")
		game.DEV.msg = msg
		game.DEV.msgT = 1.5

func img_rug() -> Image:
	var im = Image.create(128, 128, false, Image.FORMAT_RGB8)
	for y in 128:
		for x in 128:
			var d = Vector2(x - 64, y - 64).length()
			var c = Color("#6a2a5a") if int(d / 10) % 2 == 0 else Color("#e8a8c8")
			if d > 60:
				c = Color("#3a1030")
			im.set_pixel(x, y, c.darkened(randf() * 0.06))
	return im

func select_cam(id: String) -> void:
	if G.cam != id:
		G.cam = id
		G.camStatic = 0.3
		audio.sfx("cam")
		for a in ai_list():
			a.watchT = 0.0

func xp_btn(x: float, y: float, w: float, h: float, label: String, id: String, cb: Callable, on := true, size := 14.0) -> void:
	rr(x, y, w, h, 4, "#f4f3ee" if hover_btn != id else "#fff8d8", "#003c74" if on else "#a0a0a0", 1)
	while size > 9 and tw(label, size) > w - 10:
		size -= 1
	txt(label, x + w / 2, y + h / 2 + size * 0.36, size, "#000000" if on else "#a0a0a0", "center")
	if on:
		add_btn(x, y, w, h, id, cb)

func _load_store() -> void:
	if FileAccess.file_exists("user://v2.json"):
		var d = JSON.parse_string(FileAccess.get_file_as_string("user://v2.json"))
		if d is Dictionary:
			store = d

func m(c: String, rough := 0.95, metal := 0.0) -> StandardMaterial3D:
	var x = StandardMaterial3D.new()
	x.albedo_color = Color(c)
	x.roughness = rough
	x.metallic = metal
	return x

func usage() -> int:
	if G.out:
		return 0
	return 1 + int(G.doorL) + int(G.doorR) + int(G.light != null) + int(G.cams) + int(roam.on and roam.flash)

func _hit(p: Vector2):
	for i in range(buttons.size() - 1, -1, -1):
		var b: Dictionary = buttons[i]
		if p.x >= b.x and p.x <= b.x + b.w and p.y >= b.y and p.y <= b.y + b.h:
			return b
	return null

