func _bus_for(pan: float, radio: bool) -> String:
	var best := 0.0
	var bd := 9.0
	for p in PANS:
		if absf(p - pan) < bd:
			bd = absf(p - pan)
			best = p
	return ("radio" if radio else "pan") + str(best)

func lvl(a: Dictionary) -> float:
	var base: float
	if G.night == 8:
		base = CUSTOM.v if a.id == "V" else CUSTOM.c
	else:
		base = _ai_def(a.id).levels[G.night - 1][mini(5, hour_of())]
	return maxf(0.0, base - (4.0 if a.id == "V" and G.pzCalm > 0 else 0.0))

