	var d: float = audio.voice("phone|" + text, 0.35, 0.3, false)
	c.dur = maxf(3.0, d + 0.4)
	speech = {"who": "phone", "text": text, "t": 0.0, "dur": c.dur, "col": Color("#fff7c9"), "heard": true}

func _gen_buzz() -> AudioStreamWAV:
	var n := int(0.5 * SR)
	var s := PackedFloat32Array()
	s.resize(n)
	for i in n:
		s[i] = (0.25 if fmod(i * 100.0 / SR, 1.0) < 0.5 else -0.25)
	return _to_wav(s)

func _setup_people(n: int) -> void:
	var dpos = {1: Vector3(-14.2, 0, -19.4), 2: Vector3(-13.2, 0, -12.8), 3: Vector3(2.2, 0, -21.2), 4: Vector3(-3.0, 0, -14.5), 5: Vector3(1.4, 0, 1.8), 6: Vector3(-13.2, 0, -12.8), 7: Vector3(-15.0, 0, 2.0)}
	_place("D.", dpos[n], PI)
	if n == 2 or n == 6:
		for k in KIDS:
			_place(k[0], k[2], PI)
	if n == 4:
		game.COC.root.visible = false

func start_ambient() -> void:
	if not ambient.playing:
		ambient.volume_db = -30
		ambient.play()
		create_tween().tween_property(ambient, "volume_db", 0.0, 2.0)

func reset_pose() -> void:
	for r in rest:
		var j: Dictionary = r[0]
		if j.has("n"):
			var n: Node3D = j.n
			n.quaternion = r[1]
			n.position = r[2]
			n.scale = r[3]
		else:
			var sk: Skeleton3D = j.sk
			sk.set_bone_pose_rotation(j.i, r[1])
			sk.set_bone_pose_position(j.i, r[2])
			sk.set_bone_pose_scale(j.i, r[3])

func _gen_relay() -> AudioStreamWAV:
	var n := int(0.18 * SR)
	var s := PackedFloat32Array()
	s.resize(n)
	for c in [0, int(0.07 * SR)]:
		for i in int(0.03 * SR):
			s[c + i] += randf_range(-1, 1) * pow(1.0 - i / (0.03 * SR), 4) * 0.8
	return _to_wav(s)

func _process(d: float) -> void:
	acc += d
	if acc > 0.25:
		acc = 0.0
		queue_redraw()

func start_night(n: int) -> void:
	if n >= 1 and n <= 7:
		day.start_day(n)
	elif T.MINIS.has(str(n)):
		hud.start_mini(n)
	else:
		new_game(n)

func _box(sz: Vector3, m: Material, p: Vector3, parent: Node3D = null) -> MeshInstance3D:
