func pz_route(p: String) -> Array:
	var r = ["c3", "c4", "c1B", "c9", "cDOOR"]
	var i = r.find(p)
	return ["c9", "cDOOR"] if i < 0 else r.slice(i + 1)

func compute_ml():

    var xi = str2var(xi_node.text)
    var xj = str2var(xj_node.text)
    var y = str2var(y_node.text)

    var s = KomputeModelML.new()

    s.train(y, xi, xj)

    var preds = s.predict(xi, xj)

    preds_node.text = str(preds)

    var params = s.get_params()

    w1_node.set_text(str(params[0]))
    w2_node.set_text(str(params[1]))
    bias_node.set_text(str(params[2]))

func _parent_wq(j: Dictionary) -> Quaternion:
	if j.has("n"):
		return (j.n as Node3D).get_parent().global_transform.basis.get_rotation_quaternion()
	var sk: Skeleton3D = j.sk
	var p := sk.get_bone_parent(j.i)
	var b := sk.global_transform.basis.orthonormalized()
	if p >= 0:
		b = b * sk.get_bone_global_pose(p).basis.orthonormalized()
	return b.get_rotation_quaternion()

