func set_scale(role: String, s: float) -> void:
	if not has(role):
		return
	var j: Dictionary = joints[role]
	if j.has("n"):
		(j.n as Node3D).scale = Vector3.ONE * s
	else:
		(j.sk as Skeleton3D).set_bone_pose_scale(j.i, Vector3.ONE * s)

func night_name() -> String:
	if game.G.get("egg", "") != "":
		return "Po zavíračce · " + ("Voxie" if game.G.egg == "voxie" else "Cocoa")
	if game.G.get("day"):
		return "Den " + str(game.G.day)
	return "Vlastní noc" if game.G.night == 8 else "Noc " + str(game.G.night)

func _mat(c, rough := 0.8, metal := 0.0) -> StandardMaterial3D:
