	m.albedo_color = c if c is Color else Color(c)
	m.roughness = rough
	m.metallic = metal
	return m

func rotW(role: String, x: float, y: float, z: float) -> void:
	if not has(role) or (x == 0.0 and y == 0.0 and z == 0.0):
		return
	var j: Dictionary = joints[role]
	var pq := _parent_wq(j)
	var cq := root.global_transform.basis.get_rotation_quaternion()
	var q := cq * Quaternion.from_euler(Vector3(x, y, z)) * cq.inverse()
	_set_q(j, pq.inverse() * q * pq * _q(j))

func update_boot(dt: float) -> void:
	var t = scene_t
	if t > 19.2 and t - dt <= 19.2:
		audio.sfx("cam")
		audio.sfx("click")
	if t > 20.5 and t - dt <= 20.5:
		audio.sfx("fixed")
	if t > 2 and t < 17 and randf() < dt * 0.4:
		audio.sfx("drip", 0.8, randf_range(-0.8, 0.8))
	if t > 12 and t - dt <= 12:
		audio.sfx("spark", 0.5)
	if t > 35:
		S = "intro"
		scene_t = 0.0
		G.booted = true

func begin_play() -> void:
	S = "play"
	scene_t = 0.0
	audio.start_ambient()
	if G.kroupa:
		kroupa.root.visible = true
		kroupa.root.position = Vector3(-1.7, 0, 8.3)
		kroupa.walk_to = kroupa.root.position
		for l in L.nights[str(G.night)]:
			say("O", l)
		for l in L.talk.get(str(G.night), []):
			say(l[0], l[1])
	else:
		kroupa.root.visible = false

func spot_in(id: String, far: float, seed: float) -> Array:
	var r = RROOMS[id]
	for k in 80:
		var a = k * 2.4 + seed
		var rad = far + (k % 7) * 0.45
		var x = r.cx + cos(a) * rad
		var z = r.cz + sin(a) * rad
		var ok = true
		for o in [[0, 0], [0.5, 0], [-0.5, 0], [0, 0.5], [0, -0.5]]:
			if not free_at(x + o[0], z + o[1]):
				ok = false
				break
		if ok:
			return [x, z]
	return [r.cx, r.cz]

