func _gen_rattle() -> AudioStreamWAV:
	var n := int(0.9 * SR)
	var s := PackedFloat32Array()
	s.resize(n)
	for k in 12:
		var c := int((k * 0.065 + randf() * 0.02) * SR)
		for i in int(0.025 * SR):
			if c + i < n:
				s[c + i] += randf_range(-1, 1) * pow(1.0 - i / (0.025 * SR), 3) * 0.5
	return _to_wav(s)

