func harder() -> float:
	if G.night == 8:
		return CUST.hare / 10.0 + hour() * 0.05
	return (minf(G.night, 6) - 1) * 0.2 + hour() * 0.08

func rr(x: float, y: float, w: float, h: float, r: float, fill, stroke = null, lw := 2.0) -> void:
