func restore_() -> void:
	var s = xf_stack.pop_back()
	xf = s[0]
	alpha = s[1]
	_apply()

func C(c) -> Color:
	var col: Color = c if c is Color else Color(c)
	if tint_k > 0:
		col = Color(col.r * (1 - tint_k), col.g * (1 - tint_k), col.b * (1 - tint_k), col.a)
	col.a *= alpha
	return col

func vox_pose_anim(name: String, tm := -1.0) -> void:
	if not vox_anim:
		return
	if not vox_anim.has_animation(name):
		name = "Idle"
	if tm >= 0:
		if vox_anim.current_animation != name:
			vox_anim.play(name)
		vox_anim.seek(minf(tm, vox_anim.get_animation(name).length - 0.001), true)
		vox_anim.pause()
	else:
		if vox_anim.current_animation != name or not vox_anim.is_playing():
			vox_anim.play(name, 0.2)

func out_update(dt: float) -> void:
	G.outT += dt
	if G.outT < G.outDur[mini(G.outPhase, 2)]:
