func _bfs(from: String, to: String) -> Array:
	var prev = {from: ""}
	var q = [from]
	while q.size():
		var c = q.pop_front()
		if c == to:
			break
		for n in LINKS[c]:
			if not prev.has(n):
				prev[n] = c
				q.append(n)
	var out = []
	var c = to
	while prev.has(c) and prev[c] != "":
		out.push_front(c)
		c = prev[c]
	return out

