func power_tick(dt: float) -> void:
	var G = game.G
	if G.blackout:
		G.blackT += dt
		return
	var d = 0.05
	if G.door:
		d += 0.22
	if G.vent:
		d += 0.18
	if G.dl and not G.door:
		d += 0.12
	if G.vl and not G.vent:
		d += 0.1
	if G.mon:
		d += 0.06
	if G.get("fire", false):
		d *= 1.6
	G.pow = maxf(0, G.pow - d * dt)
	if G.pow <= 0:
		blackout()

